					       struct sctp_association *asoc,
					       const union sctp_addr *laddr,
					       struct sctp_chunk *chunk)
{
	struct sctp_addip_chunk *asconf;
	struct sctp_addip_param *asconf_param;
	union sctp_params param;
	union sctp_addr addr;
	struct sctp_af *af;
