	int err = 0;

	asconf = (struct sctp_addip_chunk *)chunk->chunk_data;

	sctp_walk_params(param, asconf, addip_hdr.params) {
		if (param.p->type != SCTP_PARAM_ADD_IP &&
		    param.p->type != SCTP_PARAM_DEL_IP &&
		    param.p->type != SCTP_PARAM_SET_PRIMARY)
			continue;

		error = sctp_process_asconf_param(asoc, chunk, param.addip);
		if (error != SCTP_ERROR_NO_ERROR)
			break;

		err = sctp_asconf_param_success(asoc, param.addip);
		if (err)
			break;
	}

	if (error != SCTP_ERROR_NO_ERROR)
		return sctp_sf_abort_ecn(asoc, chunk, error, 0);

	return sctp_sf_do_asconf_ack(asoc, chunk);
}
