	passwd = kstrdup(buf, GFP_KERNEL);
	if (!passwd)
		return -ENOMEM;


	strip_cr(passwd);


	auth_str = kasprintf(GFP_KERNEL, "%s,%s", passwd, setting->signature);
	if (!auth_str) {
		kfree(passwd);
		return -ENOMEM;
	}
	ret = tlmi_simple_call(LENOVO_CERT_TO_PASSWORD_GUID, auth_str);
	kfree(auth_str);
	kfree(passwd);

	return ret ?: count;
}

